'<link href="https://cdn.jsdelivr.net/npm/aos@2.3.4/dist/aos.css" rel="stylesheet" />',
'',
'<style>',
'  body {',
'    font-family: ''Segoe UI'', sans-serif;',
'    background-color: #f6f5fb;',
'    color: #333;',
'  }',
'',
'  .teams, .section-title {',
'    margin: 20px 0;',
'  }',
'',
'  .teams {',
'    display: flex;',
'    overflow-x: auto;',
'    gap: 15px;',
'    padding: 10px 0;',
'  }',
'',
'  .teams img {',
'    width: 60px;',
'    height: 60px;',
'    object-fit: contain;',
'    border-radius: 50%;',
'    border: 2px solid #ccc;',
'    background: #fff;',
'    padding: 5px;',
'  }',
'',
'  .card {',
'    display: flex;',
'    flex-direction: column;',
'    padding: 20px;',
'    border-radius: 20px;',
'    color: white;',
'    width: 260px;',
'    margin: 10px;',
'    flex-shrink: 0;',
'  }',
'',
'  .cards-row {',
'    display: flex;',
'    overflow-x: auto;',
'  }',
'',
'  .mclaren {',
'    background: linear-gradient(to right, #f36f1b, #c53c00);',
'  }',
'',
'  .mercedes {',
'    background: linear-gradient(to right, #00c6c2, #007f7f);',
'  }',
'',
'  .redbull {',
'    background: linear-gradient(to right, #1e3c72, #2a5298);',
'  }',
'',
'  .ferrari {',
'    background: linear-gradient(to right, #ff4c4c, #cc0000);',
'  }',
'',
'  .williams {',
'    background: linear-gradient(to right, #041E42, #00A4E0);',
'  }',
'',
'  .haas {',
'    background: linear-gradient(to left, #F9F2F2, #F62039);',
'  }',
'',
'  .card h3 {',
'    font-size: 1.5em;',
'    margin-bottom: 5px;',
'  }',
'',
