'    display: block;',
'    margin-top: 8px;',
'    font-weight: bold;',
'  }',
'</style>',
'',
'<!-- HTML Content -->',
' <a href="f?p=&APP_ID.:36:&SESSION.::NO:::" title="Ir a campeonato de constructores">',
