,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<!DOCTYPE html>',
'<html lang="es">',
'<head>',
'  <meta charset="UTF-8">',
'  <meta name="viewport" content="width=device-width, initial-scale=1.0">',
'  <title>F1 Manager</title>',
'  <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.0/css/all.min.css">',
'  <style>',
'    body {',
'      margin: 0;',
'      font-family: ''Segoe UI'', sans-serif;',
'      background-color: #fff5f8;',
'      text-align: center;',
'    }',
'',
'    .logo {',
'      margin-top: 20px;',
'    }',
'',
'    .menu-container {',
'      display: flex;',
'      flex-wrap: wrap;',
'      justify-content: center;',
'      gap: 2rem;',
'      padding: 2rem;',
'    }',
'',
'    .card {',
'      width: 280px;',
'      height: 300px;',
'      border-radius: 2rem;',
'      color: white;',
'      font-size: 1.5rem;',
'      font-weight: bold;',
'      display: flex;',
'      flex-direction: column;',
'      align-items: center;',
'      justify-content: space-between;',
'      padding: 1rem;',
'      box-shadow: 0 5px 15px rgba(0,0,0,0.2);',
'      transition: transform 0.3s ease;',
'      text-shadow: 1px 1px 2px black;',
'    }',
'',
'    .card:hover {',
'      transform: scale(1.05);',
'      cursor: pointer;',
'    }',
'',
'    .piloto {',
'      background: linear-gradient(to right, #0d0c69, #1f1fae);',
'    }',
'',
'    .equipo {',
'      background: linear-gradient(to right, #ffcc00, #b80000);',
'    }',
'',
'    .patro-piloto {',
'      background: linear-gradient(to right, #ffa500, #ff4500);',
'    }',
'',
'    .patro-equipo {',
'      background: linear-gradient(to right, #6a11cb, #2575fc);',
'    }',
'',
'    .card img {',
'      max-width: 100%;',
'      max-height: 180px;',
'      object-fit: contain;',
'    }',
'',
'    .title {',
'      margin: 0;',
'    }',
'  </style>',
'</head>',
'<body>',
'',
'  <div class="logo">',
'    <img src="https://upload.wikimedia.org/wikipedia/commons/thumb/3/33/F1.svg/2560px-F1.svg.png" alt="F1 Logo" width="200">',
'    <h1 style="font-family: ''Orbitron'', sans-serif; letter-spacing: 2px;">MANAGER</h1>',
'  </div>',
'',
'  <div class="menu-container">',
unistr('    <!-- A\00F1adir Piloto -->'),
'    <div class="card piloto">',
unistr('      <div>A\00D1ADIR</div>'),
'       <a href="f?p=&APP_ID.:42:&SESSION.::NO:::" title="Ir a agregar Piloto">',
'      <img src="#APP_FILES#imagen-removebg-preview(1).png" alt="Piloto">',
'      <div>PILOTO</div>',
'    </div>',
'    </a>',
unistr('    <!-- A\00F1adir Equipo -->'),
'    <div class="card equipo">',
unistr('      <div>A\00D1ADIR</div>'),
'       <a href="f?p=&APP_ID.:43:&SESSION.::NO:::" title="Ir a agregar Piloto">',
'      <img src="#APP_FILES#carros/caritototootototo.png" alt="Equipo">',
'      <div>EQUIPO</div>',
'    </div>',
'    </a>',
'',
unistr('    <!-- A\00F1adir Patrocinador a Piloto -->'),
'    <div class="card patro-piloto">',
unistr('      <div>A\00D1ADIR</div>'),
'       <a href="f?p=&APP_ID.:44:&SESSION.::NO:::" title="Ir a agregar patrcinador piloto">',
'      <img src="#APP_FILES#patrocinadororoor-removebg-preview.png" alt="patrocinador piloto">',
'      <div>PATROCINADOR A PILOTO</div>',
'    </div>',
'    </a>',
unistr('    <!-- A\00F1adir Patrocinador a Equipo -->'),
