wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(48430806572162148262)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'cargar_ferrari'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  v_puesto  tf_equipo.puesto%TYPE;',
'  v_puntos  tf_equipo.puntos%TYPE;',
'  v_pilotos VARCHAR2(100);',
'BEGIN',
'  -- Obtener puesto y puntos del equipo con ID 4',
'  SELECT puesto, puntos',
'  INTO v_puesto, v_puntos',
'  FROM tf_equipo',
'  WHERE id_equipo = 4;',
'',
'  -- Obtener nombres de los pilotos del equipo con ID 4, concatenados con " - "',
'  SELECT LISTAGG(nombre, '' - '') WITHIN GROUP (ORDER BY nombre)',
'  INTO v_pilotos',
'  FROM tf_corredor',
'  WHERE id_equipo = 4;',
'',
'  -- Asignar a variables bind',
'  :PUESTOFER := v_puesto;',
'  :PUNTOSFER := v_puntos;',
'  :PILOTOSFER := v_pilotos;',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>48430806572162148262
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(48217671545807324833)
,p_process_sequence=>20
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'cargar_haas'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  v_puesto  tf_equipo.puesto%TYPE;',
'  v_puntos  tf_equipo.puntos%TYPE;',
'  v_pilotos VARCHAR2(100);',
'BEGIN',
'  -- Obtener puesto y puntos del equipo con ID 4',
'  SELECT puesto, puntos',
'  INTO v_puesto, v_puntos',
'  FROM tf_equipo',
'  WHERE id_equipo = 10;',
'',
'  -- Obtener nombres de los pilotos del equipo con ID 4, concatenados con " - "',
'  SELECT LISTAGG(nombre, '' - '') WITHIN GROUP (ORDER BY nombre)',
'  INTO v_pilotos',
'  FROM tf_corredor',
'  WHERE id_equipo = 10;',
'',
'  -- Asignar a variables bind',
'  :PUESTOHAAS := v_puesto;',
'  :PUNTOSHAAS := v_puntos;',
'  :PILOTOSHAAS := v_pilotos;',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>48217671545807324833
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(48430806977840148262)
,p_process_sequence=>30
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'cargar_patrociniosferrari'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_html CLOB := '''';',
'BEGIN',
'    FOR rec IN (',
'        SELECT p.nombre',
'        FROM tf_patrocinador p',
'        JOIN tf_equipo_patrocinador ep ON p.id_patrocinador = ep.id_patrocinador',
'        WHERE ep.id_equipo = 4 -- Ferrari',
'    ) LOOP',
'        -- Concatenamos solo el nombre con coma y espacio',
'        IF v_html IS NULL OR v_html = '''' THEN',
'            v_html := rec.nombre;',
'        ELSE',
'            v_html := v_html || '', '' || rec.nombre;',
'        END IF;',
'    END LOOP;',
'',
'    :PATROCINADORES_HTML := v_html;',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>48430806977840148262
);
